import React from "react";
import useDinkManager from "../../state/useDinkManager";
import { hydratePersistedState, StorageUnavailableError } from "../../state/storage";

const AppStateContext = React.createContext(null);
AppStateContext.displayName = "AppStateContext";

function AppStateInner({ initialState, children }) {
  const state = useDinkManager(initialState);
  return <AppStateContext.Provider value={state}>{children}</AppStateContext.Provider>;
}

export function AppStateProvider({ children, bootstrapState = null }) {
  const [hydrated, setHydrated] = React.useState(() =>
    bootstrapState != null ? bootstrapState : null
  );
  const [storageError, setStorageError] = React.useState(null);

  React.useEffect(() => {
    if (bootstrapState != null) return undefined;
    let cancelled = false;
    (async () => {
      try {
        const raw = await hydratePersistedState();
        if (!cancelled) {
          setHydrated(raw || {});
          setStorageError(null);
        }
      } catch (err) {
        console.error("Failed to hydrate app state", err);
        if (!cancelled) {
          setStorageError(
            err instanceof StorageUnavailableError
              ? err.message
              : "Could not load saved data from this browser. Check that site data is allowed, then reload."
          );
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [bootstrapState]);

  if (storageError) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-pt-navy text-white px-6 text-center gap-3">
        <p className="text-lg font-semibold">Storage unavailable</p>
        <p className="text-sm text-white/80 max-w-md">{storageError}</p>
        <p className="text-xs text-white/60">Staff: allow cookies/site data for this app, then reload.</p>
      </div>
    );
  }

  if (hydrated === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-pt-navy text-white/70 text-sm">
        Loading Dink Manager…
      </div>
    );
  }

  return <AppStateInner initialState={hydrated}>{children}</AppStateInner>;
}

export function useAppState(selector) {
  const context = React.useContext(AppStateContext);
  if (!context) {
    throw new Error("useAppState must be used within an AppStateProvider");
  }
  return React.useMemo(() => {
    if (typeof selector === "function") {
      return selector(context);
    }
    return context;
  }, [context, selector]);
}
