import { isPlayerUnpaid } from "./paymentStatus";
import { getOpenPlayPrice, getRentalBookingFinancials } from "./pricing";
import { isOpenPlayCalendarBlock } from "./openPlayBlock";

export { isOpenPlayCalendarBlock } from "./openPlayBlock";

/** Local civil calendar date YYYY-MM-DD (never UTC slice). */
export const toYMDLocal = (dateLike) => {
  if (!dateLike && dateLike !== 0) return "";
  if (typeof dateLike === "string" && /^\d{4}-\d{2}-\d{2}$/.test(dateLike)) return dateLike;

  const d =
    dateLike instanceof Date
      ? dateLike
      : typeof dateLike === "number"
        ? new Date(dateLike)
        : new Date(dateLike);

  if (!Number.isFinite(d.getTime())) return "";
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
};

/** False only for typed OPEN_PLAY_BLOCK. Named "OPEN PLAY" rentals stay true. */
export const isRentalBooking = (booking) =>
  !!booking && !isOpenPlayCalendarBlock(booking);

export const isReportableOpSession = (session) =>
  String(session?.status || "").toLowerCase() !== "cancelled";

export const slotCourtHours = (slot) => {
  if (!slot) return 0;
  if (typeof slot.startTime === "number" && typeof slot.endTime === "number") {
    return Math.max(0, (slot.endTime - slot.startTime) / 60);
  }
  const start = new Date(slot.startTime);
  const end = new Date(slot.endTime);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime())) return 0;
  return Math.max(0, (end - start) / (1000 * 60 * 60));
};

export const slotYMD = (slot) => {
  if (!slot) return "";
  if (slot.date && /^\d{4}-\d{2}-\d{2}$/.test(slot.date)) return slot.date;
  if (typeof slot.startTime === "number") return "";
  return toYMDLocal(slot.startTime);
};

/** Active slots for a booking from slotsV2 map. */
export const getBookingActiveSlots = (bookingId, slotsV2 = {}) =>
  Object.values(slotsV2).filter(
    (s) => s && s.bookingId === bookingId && s.status !== "CANCELLED"
  );

/** Earliest slot YMD for a booking (for multi-day attribution). */
export const getEarliestSlotYMD = (bookingId, slotsV2 = {}) => {
  const slots = getBookingActiveSlots(bookingId, slotsV2)
    .filter((s) => slotYMD(s))
    .sort((a, b) => {
      const d = slotYMD(a).localeCompare(slotYMD(b));
      if (d !== 0) return d;
      const tA = typeof a.startTime === "number" ? a.startTime : 0;
      const tB = typeof b.startTime === "number" ? b.startTime : 0;
      return tA - tB;
    });
  return slots.length ? slotYMD(slots[0]) : "";
};

/**
 * Rental amountPaid attributed to a single calendar day (earliest slot only).
 */
export const attributeRentalPaidToYmd = (booking, slotsV2, dayYmd) => {
  if (!isRentalBooking(booking) || !dayYmd) return 0;
  const earliest = getEarliestSlotYMD(booking?.id, slotsV2);
  if (earliest !== dayYmd) return 0;
  const { amountPaid } = getRentalBookingFinancials(booking, slotsV2);
  return amountPaid > 0 ? amountPaid : 0;
};

export const unpaidOpenPlayAmount = (player, settings = {}, sessionFee = null) => {
  if (!player || !isPlayerUnpaid(player.paymentStatus, player.paymentMethod)) return 0;
  const price = typeof player.price === "number" ? player.price : 0;
  if (price > 0) return price;
  return getOpenPlayPrice(settings, {
    isMember: !!player.isMember,
    sessionFee: sessionFee ?? settings?.defaultOpFee ?? 0,
  });
};

/** Parse YYYY-MM-DD as local midnight Date. */
export const parseYMDLocal = (ymd) => {
  if (!ymd || !/^\d{4}-\d{2}-\d{2}$/.test(ymd)) return null;
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(y, m - 1, d, 0, 0, 0, 0);
};

/** Inclusive day count between two YMD strings. */
export const daysBetweenYMD = (startYmd, endYmd) => {
  const start = parseYMDLocal(startYmd);
  const end = parseYMDLocal(endYmd);
  if (!start || !end || start > end) return 0;
  return Math.round((end - start) / (1000 * 60 * 60 * 24)) + 1;
};
