import { commitOp, readDeviceRecord } from "./entityStore";
import { isDisplaySurface, getVoicePrefsSync, rememberVoicePrefs } from "./storage";
import { isLeaderboardSurface } from "./e2eMode";

const VOICE_DEFAULTS = { voiceName: "", rate: 0.9, pitch: 1 };

let cache = null;
const listeners = new Set();

export function getVoiceSync() {
  if (cache) return cache;
  const fromIdb = getVoicePrefsSync();
  return {
    voiceName: fromIdb.voiceName || VOICE_DEFAULTS.voiceName,
    rate: Number(fromIdb.rate ?? VOICE_DEFAULTS.rate),
    pitch: Number(fromIdb.pitch ?? VOICE_DEFAULTS.pitch),
  };
}

function emit() {
  const snap = getVoiceSync();
  listeners.forEach((listener) => listener(snap));
}

export function subscribeVoice(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export async function hydrateVoiceSettings() {
  const row = await readDeviceRecord("voice");
  if (row?.data) {
    cache = {
      voiceName: row.data.voiceName || "",
      rate: Number(row.data.rate ?? VOICE_DEFAULTS.rate),
      pitch: Number(row.data.pitch ?? VOICE_DEFAULTS.pitch),
    };
    rememberVoicePrefs(cache);
    emit();
    return cache;
  }
  cache = getVoiceSync();
  rememberVoicePrefs(cache);
  return cache;
}

export async function saveVoiceSettings(next) {
  const voice = {
    voiceName: next?.voiceName || "",
    rate: Number(next?.rate ?? VOICE_DEFAULTS.rate),
    pitch: Number(next?.pitch ?? VOICE_DEFAULTS.pitch),
  };
  cache = voice;
  rememberVoicePrefs(voice);
  emit();
  if (isDisplaySurface() || isLeaderboardSurface()) return voice;
  let last = null;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const existing = await readDeviceRecord("voice");
    if (existing?.data
      && (existing.data.voiceName || "") === voice.voiceName
      && Number(existing.data.rate) === voice.rate
      && Number(existing.data.pitch) === voice.pitch) {
      return voice;
    }
    last = await commitOp({
      opId: `voice:${Date.now()}:${Math.random().toString(36).slice(2, 6)}`,
      actorId: "voice",
      writes: [{
        kind: "device",
        id: "voice",
        baseRev: existing?.rev || 0,
        base: existing?.data || null,
        next: voice,
      }],
      tombstones: [],
    }, { writer: "staff" });
    if (last?.ok) return voice;
    if (last?.reason !== "conflict" && last?.reason !== "abort" && last?.reason !== "unavailable") break;
  }
  return voice;
}
