export function isE2EMode(env = process.env.NODE_ENV) {
  if (env === "production") return false;
  if (typeof window === "undefined") return false;
  const search = String(window.location.search || "");
  const hash = String(window.location.hash || "");
  return /(?:\?|&)e2e=1(?:&|$)/.test(search) || /(?:\?|&)e2e=1(?:&|$)/.test(hash);
}

export function isLeaderboardSurface() {
  if (typeof window === "undefined") return false;
  const hash = String(window.location.hash || "");
  return /#\/leaderboards?(?:\/|$|\?)/.test(hash);
}
