import toast from "react-hot-toast";
import { commitOp, readDeviceRecord } from "../../../state/entityStore";
import { getLeaderboardDisplaySync, isDisplaySurface, rememberLeaderboardDisplay } from "../../../state/storage";
import { formatReclubIdLabel, resolveReclubDisplay } from "../../queue/utils/reclubPlayer";

const idKey = (value) => String(value ?? "");

const emptyRow = (player = {}) => {
  const identity = resolveReclubDisplay(player);
  return {
    id: idKey(player.id),
    name: player.name || "Player",
    level: player.level || "—",
    matches: 0,
    wins: 0,
    losses: 0,
    points: 0,
    snapshotPoints: Number.isFinite(Number(player.pointDifferential)) ? Number(player.pointDifferential) : 0,
    scoredFromMatches: false,
    imageUrl: player.imageUrl || player.photo || player.avatarUrl || null,
    reclubUserId: identity.reclubUserId,
    isGuest: identity.isGuest,
    // Drop a bare referenceId from the computed row so a later label pass cannot treat it as a user id.
    referenceId: identity.reclubUserId != null || identity.isGuest === true ? (player.referenceId ?? null) : null,
    referenceType: identity.reclubUserId != null || identity.isGuest === true ? (player.referenceType ?? null) : null,
  };
};

/** Same PD rule as live stats: absolute score margin. */
function pointDiffFromMatch(match) {
  const greenScore = Number(match?.score?.green);
  const blueScore = Number(match?.score?.blue);
  if (!Number.isFinite(greenScore) || !Number.isFinite(blueScore)) return null;
  if (greenScore === blueScore) return 0;
  return Math.abs(greenScore - blueScore);
}

export const LEADERBOARD_MIN_MATCHES = 5;

export function isRankedLeaderboardRow(row) {
  return (row?.matches || 0) >= LEADERBOARD_MIN_MATCHES;
}

/** Rank: win rate, then wins, then PD, then matches played, then name A–Z. */
export function compareLeaderboardRows(a, b) {
  if ((b.winRate || 0) !== (a.winRate || 0)) return (b.winRate || 0) - (a.winRate || 0);
  if ((b.wins || 0) !== (a.wins || 0)) return (b.wins || 0) - (a.wins || 0);
  if ((b.points || 0) !== (a.points || 0)) return (b.points || 0) - (a.points || 0);
  if ((b.matches || 0) !== (a.matches || 0)) return (b.matches || 0) - (a.matches || 0);
  return String(a.name || "").localeCompare(String(b.name || ""));
}

/** Ranked rows first (1…N), then unranked; each group sorted with compareLeaderboardRows. */
export function orderLeaderboardRows(rows = []) {
  const list = Array.isArray(rows) ? rows : [];
  const ranked = list.filter(isRankedLeaderboardRow).sort(compareLeaderboardRows);
  const unranked = list.filter((row) => !isRankedLeaderboardRow(row)).sort(compareLeaderboardRows);
  return [
    ...ranked.map((row, index) => ({ ...row, rank: index + 1 })),
    ...unranked.map((row) => ({ ...row, rank: null })),
  ];
}

/**
 * All-player leaderboard from a roster + completed matches.
 * Columns: Matches | Win Rate | Win | Lose | PD | Level
 */
export function buildPlayerLeaderboard(players = [], matches = []) {
  const stats = new Map();

  (Array.isArray(players) ? players : []).forEach((player) => {
    if (!player || player.id == null) return;
    stats.set(idKey(player.id), emptyRow(player));
  });

  (Array.isArray(matches) ? matches : []).forEach((match) => {
    if (!match || match.status !== "completed" || !match.winner) return;
    const green = Array.isArray(match.teams?.green) ? match.teams.green : [];
    const blue = Array.isArray(match.teams?.blue) ? match.teams.blue : [];
    const winner = match.winner;
    const diff = pointDiffFromMatch(match);
    [...green, ...blue].forEach((rawId) => {
      const key = idKey(rawId);
      const row = stats.get(key);
      if (!row) return;
      const onGreen = green.some((id) => idKey(id) === key);
      const won = (winner === "green" && onGreen) || (winner === "blue" && !onGreen);
      row.matches += 1;
      if (won) row.wins += 1;
      else row.losses += 1;
      if (diff != null) {
        row.scoredFromMatches = true;
        row.points += won ? diff : -diff;
      }
    });
  });

  const mapped = Array.from(stats.values()).map((row) => {
    const { snapshotPoints, scoredFromMatches, ...rest } = row;
    return {
      ...rest,
      points: scoredFromMatches ? row.points : snapshotPoints,
      winRate: row.matches > 0 ? Math.round((row.wins / row.matches) * 100) : 0,
    };
  });
  return orderLeaderboardRows(mapped);
}

export function sliceLeaderboardTop(rows = [], n = 5) {
  return orderLeaderboardRows(rows).filter(isRankedLeaderboardRow).slice(0, n);
}

export const LEADERBOARD_CSV_HEADERS = [
  "Rank",
  "Player",
  "Reclub ID",
  "Matches",
  "Win Rate",
  "Win",
  "Lose",
  "PD",
  "Level",
];

/** Rank cell used by the table and CSV. Unranked players (under the match floor) are an em dash. */
export function formatLeaderboardRank(row) {
  return row?.rank == null ? "—" : String(row.rank);
}

/** Table display. CSV uses formatLeaderboardCsvPoints so a leading + is not written. */
export function formatLeaderboardPoints(value) {
  const n = Number(value) || 0;
  if (n > 0) return `+${n}`;
  return String(n);
}

export function formatLeaderboardCsvPoints(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "0";
  return String(n);
}

function formatLeaderboardCsvWinRate(value) {
  const n = Number(value);
  const rate = Number.isFinite(n) ? n : 0;
  return `${rate}%`;
}

function formatLeaderboardCsvCount(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "0";
  return String(n);
}

const CSV_FORMULA_START = /^[=+\-@\t\r]/;

/**
 * Text cells: a leading = + - @ tab or CR is prefixed with ' so a spreadsheet
 * does not treat the cell as a formula, then normal CSV quoting is applied.
 * Do not use this for numeric columns (a signed PD must stay a number).
 */
export function escapeCsvField(value) {
  let text = value == null ? "" : String(value);
  if (CSV_FORMULA_START.test(text)) text = `'${text}`;
  if (/[",\r\n]/.test(text)) return `"${text.replace(/"/g, '""')}"`;
  return text;
}

export function leaderboardRowsToCsv(rows = []) {
  const lines = [LEADERBOARD_CSV_HEADERS.map(escapeCsvField).join(",")];
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const cells = [
      escapeCsvField(formatLeaderboardRank(row)),
      escapeCsvField(row?.name ?? ""),
      escapeCsvField(formatReclubIdLabel(row)),
      formatLeaderboardCsvCount(row?.matches),
      formatLeaderboardCsvWinRate(row?.winRate),
      formatLeaderboardCsvCount(row?.wins),
      formatLeaderboardCsvCount(row?.losses),
      formatLeaderboardCsvPoints(row?.points),
      escapeCsvField(row?.level || "—"),
    ];
    lines.push(cells.join(","));
  });
  return `${lines.join("\n")}\n`;
}

export function leaderboardCsvFilename(scope = "live") {
  const slug = String(scope || "live")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || "session";
  return `leaderboard-${slug}.csv`;
}

export const LEADERBOARD_DISPLAY_EVENT = "SHOW_PLAYER_LEADERBOARD";
export const LEADERBOARD_DISPLAY_MS = 120000;
export const LEADERBOARD_DISPLAY_STORAGE_KEY = "southDinkersLeaderboardDisplayUntil";
export const LEADERBOARD_DISPLAY_MODE = {
  FULL: "full",
  TOP5: "top5",
};

function normalizeDisplayMode(mode) {
  return mode === LEADERBOARD_DISPLAY_MODE.TOP5
    ? LEADERBOARD_DISPLAY_MODE.TOP5
    : LEADERBOARD_DISPLAY_MODE.FULL;
}

function publishLeaderboardDisplay({ until, mode }) {
  const payload = {
    until: Number(until) || 0,
    mode: normalizeDisplayMode(mode),
  };
  if (isDisplaySurface()) return;
  rememberLeaderboardDisplay(payload);
  void (async () => {
    const existing = await readDeviceRecord("leaderboardDisplay");
    const result = await commitOp({
      opId: `board:${Date.now()}:${Math.random().toString(36).slice(2, 6)}`,
      actorId: "leaderboard-display",
      writes: [{
        kind: "device",
        id: "leaderboardDisplay",
        baseRev: existing?.rev || 0,
        base: existing?.data || null,
        next: payload,
      }],
      tombstones: [],
    }, { writer: "staff" });
    if (result && !result.ok && result.reason !== "noop" && result.reason !== "read-only") {
      toast.error(
        "Could not save leaderboard display in this browser. Check that site data is allowed.",
        { id: "leaderboard-display-save-fail" }
      );
    }
  })();
  if (typeof window !== "undefined" && "BroadcastChannel" in window) {
    const bc = new BroadcastChannel("dink_manager");
    bc.postMessage({ type: LEADERBOARD_DISPLAY_EVENT, until: payload.until, mode: payload.mode });
    bc.close();
  }
}

export function requestLeaderboardDisplay(
  durationMs = LEADERBOARD_DISPLAY_MS,
  mode = LEADERBOARD_DISPLAY_MODE.FULL
) {
  const until = Date.now() + durationMs;
  publishLeaderboardDisplay({ until, mode });
  return until;
}

/** Hide the TV display overlay immediately (does not overlay the admin tab). */
export function clearLeaderboardDisplay() {
  publishLeaderboardDisplay({ until: 0, mode: LEADERBOARD_DISPLAY_MODE.FULL });
}

export function readLeaderboardDisplay() {
  const stored = getLeaderboardDisplaySync();
  return {
    until: Number(stored.until) || 0,
    mode: normalizeDisplayMode(stored.mode),
  };
}

export function readLeaderboardDisplayUntil() {
  return readLeaderboardDisplay().until;
}

export function remainingLeaderboardDisplayMs(now = Date.now()) {
  return Math.max(0, readLeaderboardDisplayUntil() - now);
}
