import config from "../../config";

const API_BASE = process.env.REACT_APP_API_URL || "";
const FACILITY_ID = process.env.REACT_APP_FACILITY_ID || config.facilityId;

const parseJson = async (res) => {
  try {
    return await res.json();
  } catch {
    return {};
  }
};

export async function verifyAdminPassword(password) {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/verify-password`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ password }),
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not verify password");
    err.code = data.error;
    throw err;
  }
  return data;
}

export async function changeAdminPassword({ oldPassword, newPassword, confirmPassword }) {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/password`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ oldPassword, newPassword, confirmPassword }),
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not change password");
    err.code = data.error;
    throw err;
  }
  return data;
}
